    subSkill: {
      block: {
        mod: {
          playerEnabled(card, player, target) {
            if (player !== target) {
              return false;
            }
          }
        }
      },
      choose: {
        trigger: { player: "phaseJieshuBegin" },
        direct: true,
        filter(event, player) {
          return player.countCards("he") > 0;
        },
        async content(event, trigger, player) {
          const result2 = await player.chooseCard({
            prompt: get.prompt("mingfa"),
            prompt2: "选择展示自己的一张牌",
