        list.push("cancel2");
      }
      const getn = (group) => game.countPlayer((current) => {
        if (current.group !== group) {
          return false;
        }
        if (player === current) {
          return 2;
        }
        if (get.attitude(current, player) > 0) {
          return 1;
        }
        return 1.3;
      });
