shiji:mbfubi.code:
{
    audio: "fubi",
    enable: "phaseUse",
    usable: 1,
    filterTarget: true,
    async content(event, trigger, player) {
      const { target } = event;
      const storage = target.storage.mbdingyi_buff ?? [0, 0, 0, 0];
      const result2 = await player.chooseButton({
        createDialog: [
          `辅弼：令${get.translation(target)}获得一个“定仪”效果或令其所有“定仪”效果翻倍`,
          [
            [
              ["draw", "摸牌阶段摸牌数+1"],
              ["maxhand", "手牌上限+2"],
              ["attack", "攻击范围+1"],
              ["dying", "脱离濒死状态时回复1点体力"],
              ["double", `令${get.translation(target)}所有“定仪”效果翻倍`]
            ],
            "textbutton"
          ]
        ],
        filterButton(button) {
          const { storage: storage2 } = get.event();
          const link = button.link;
          switch (link) {
            case "draw":
              return storage2[0] == 0;
            case "maxhand":
              return storage2[1] == 0;
            case "attack":
              return storage2[2] == 0;
            case "dying":
              return storage2[3] == 0;
            default:
              return storage2.some((i) => i > 0);
          }
        },
        forced: true,
        ai(button) {
          const link = button.link;
          switch (link) {
            case "draw":
              return 10;
            case "maxhand":
              return 8;
            case "attack":
              return 3;
            case "dying":
              return 5;
            default:
              return 2;
          }
        }
      }).set("storage", storage).forResult();
      if (result2?.bool && result2.links?.length) {
        const link = result2.links[0];
        target.addSkill("mbdingyi_buff");
        switch (link) {
          case "draw":
            storage[0]++;
            break;
          case "maxhand":
            storage[1] += 2;
            break;
          case "attack":
            storage[2]++;
            break;
          case "dying":
            storage[3]++;
            break;
          default:
            storage[0] *= 2;
            storage[1] *= 2;
            storage[2] *= 2;
            storage[3] *= 2;
        }
        target.setStorage("mbdingyi_buff", storage, true);
        if (link == "double") {
          game.log(player, "令", target, "的“定仪”效果翻倍");
          player.addSkill(event.name + "_clear");
          player.markAuto(event.name + "_clear", [target]);
        }
      }
    },
    ai: {
      order: 5,
      result: {
        player: 1,
        target: 1
      }
    },
    subSkill: {
      clear: {
        charlotte: true,
        silent: true,
        popup: false,
        trigger: { player: "phaseUseBegin" },
        onremove: true,
        async content(event, trigger, player) {
          const targets = player.getStorage(event.name);
          for (const target of targets) {
            const storage = target.storage.mbdingyi_buff ?? [0, 0, 0, 0];
            if (storage.some((i) => i > 1)) {
              for (let i = 0; i < 4; i++) {
                if (storage[i] > 1) {
                  const num = Math.ceil(storage[i] / 2);
                  storage[i] -= num;
                }
              }
              target.setStorage("mbdingyi_buff", storage, true);
            }
          }
          player.removeSkill(event.name);
        }
      }
    }
  }

